package io.aetheris.orchestrator.trading;
import jakarta.transaction.Transactional;import org.springframework.stereotype.Service;import java.time.Duration;import java.util.*;
@Service public class PaperTradingService {private final TradingIntelligenceService intelligence;private final PaperAccountRepository accounts;private final PaperPositionRepository positions;private final PaperJournalRepository journal;private final PaperRiskOfficerService risk;private final ManualMarketDataAdapter market;public PaperTradingService(TradingIntelligenceService intelligence,PaperAccountRepository accounts,PaperPositionRepository positions,PaperJournalRepository journal,PaperRiskOfficerService risk,ManualMarketDataAdapter market){this.intelligence=intelligence;this.accounts=accounts;this.positions=positions;this.journal=journal;this.risk=risk;this.market=market;}public PaperAccountEntity account(){return accounts.findById("paper-default").orElseGet(()->accounts.save(new PaperAccountEntity("paper-default",10000)));}@Transactional public PaperExecutionResult open(UUID signalId){TradeSignalEntity signal=intelligence.required(signalId);if(positions.existsBySignalId(signalId))return new PaperExecutionResult(false,"PAPER_ONLY","Signal already has a paper position",positions.findTop100ByOrderByOpenedAtDesc().stream().filter(p->p.getSignalId().equals(signalId)).findFirst().orElse(null),null);PaperRiskPolicyEntity pp=risk.policy();MarketDataSnapshot snapshot=market.latest(signal.getSymbol(),Duration.ofSeconds(pp.getMaxStaleDataSeconds()));double fill=snapshot.bars().getLast().close();PaperAccountEntity account=account();PaperRiskDecision decision=risk.evaluate(account,signal,fill);if(!decision.allowed()){journal.save(new PaperJournalEntity(UUID.randomUUID(),signal.getSymbol(),"RISK_REJECTED",String.join(" | ",decision.reasons()),null));return new PaperExecutionResult(false,"PAPER_ONLY","Risk Officer rejected paper trade",null,decision);}double notional=Math.min(signal.getRecommendedNotional(),account.getCashBalance()*signal.getLeverage());double qty=notional/fill;PaperPositionEntity position=positions.save(new PaperPositionEntity(UUID.randomUUID(),signal,fill,qty));journal.save(new PaperJournalEntity(UUID.randomUUID(),signal.getSymbol(),"PAPER_OPEN","Simulated fill at "+fill+"; no exchange order was sent.",null));return new PaperExecutionResult(true,"PAPER_ONLY","Paper position opened; live execution is not implemented",position,decision);}@Transactional public PaperPositionEntity close(UUID positionId,double requestedPrice){PaperPositionEntity p=positions.findById(positionId).orElseThrow(()->new NoSuchElementException("Unknown paper position"));PaperRiskPolicyEntity pp=risk.policy();double exit=requestedPrice>0?requestedPrice:market.latest(p.getSymbol(),Duration.ofSeconds(pp.getMaxStaleDataSeconds())).bars().getLast().close();double pnl=p.close(exit);positions.save(p);PaperAccountEntity a=account();a.realize(pnl);accounts.save(a);journal.save(new PaperJournalEntity(UUID.randomUUID(),p.getSymbol(),"PAPER_CLOSE","Paper position closed at "+exit,pnl));return p;}public List<PaperPositionEntity> positions(){return positions.findTop100ByOrderByOpenedAtDesc();}public List<PaperJournalEntity> journal(){return journal.findTop200ByOrderByCreatedAtDesc();}}
